#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

#
# The fresh-schema cutover (#104): the live data moves onto the squash's fresh schema, in place, with one
# all-or-nothing cutover.sql. Someone with access to the shared Cloudflare account runs it on the evening
# #112 is released, from a clean checkout of this folder's branch. Never an agent: every stage reaches the
# live database.
#   bash scripts/fresh-schema-cutover/wizard.sh        from the start
#   bash scripts/fresh-schema-cutover/wizard.sh 4      resume at stage 4; every stage reads where things stand
# The plan and its reasons: README.md here, #104 and #92. .cutover.env (git-ignored) remembers tonight's
# bookmarks, versions and times. out/ holds the backup, which holds personal data; stage 7 deletes it.

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO="$(cd "$HERE/../.." && pwd)"
OUT="$HERE/out"
WR="${WRANGLER:-$REPO/node_modules/.bin/wrangler}"
CONFIG="$REPO/wrangler.jsonc"
LIVE=(--remote --config "$CONFIG")
SQUASH_PR=112
GITHUB_REPO=isayulee/CSA-ID
# shellcheck source=lib.sh
source "$HERE/lib.sh"

show() { printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"; }
# must "what to do if it fails" COMMAND...: run COMMAND, or explain and stop.
must() { local help="$1"; shift; show "$*"; if ! "$@"; then warn "$help"; exit 1; fi; }
# load KEY...: the values an earlier run saved in .cutover.env (empty when there are none).
load() { local k; for k in "$@"; do printf -v "$k" '%s' "$(_existing "$k" || true)"; done; }
# ask_valid KEY "Prompt" REGEX "hint": ask until the answer matches.
ask_valid() {
  local key="$1" prompt="$2" pattern="$3" hint="$4"
  while true; do
    ask "$key" "$prompt" || exit 1
    [[ "${!key}" =~ $pattern ]] && return 0
    warn "$hint"
  done
}
when() { node -e 'console.log(new Date(Number(process.argv[1]) * 1000).toLocaleString())' "$1"; }
indent() { sed '/./s/^/    /'; }
# json_field NAME: one field of the JSON object on stdin.
json_field() {
  node -e 'let s = ""; process.stdin.on("data", (d) => (s += d)).on("end", () => {
    try { const v = JSON.parse(s)[process.argv[1]]; if (!v) process.exit(1); console.log(v); } catch { process.exit(1); } })' "$1"
}
# current_bookmark: the live database's Time Travel bookmark for this moment. Read only.
current_bookmark() { "$WR" d1 time-travel info "$DB_NAME" --json --config "$CONFIG" | json_field bookmark; }
# live_version: the id of the Worker version that serves all traffic now. Read only.
live_version() {
  "$WR" deployments list --json --config "$CONFIG" | node -e '
    const d = JSON.parse(require("fs").readFileSync(0, "utf8")).sort((a, b) => a.created_on.localeCompare(b.created_on));
    const v = d.length && d[d.length - 1].versions.find((x) => x.percentage === 100);
    if (!v) process.exit(1);
    console.log(v.version_id)'
}
# same_fresh_schema REF: REF holds the very 0000 that cutover.sql is built from.
same_fresh_schema() {
  [[ "$(git show "$1:migrations/$FRESH_MIGRATION" 2> /dev/null | tr -d '\r')" == "$(tr -d '\r' < "$REPO/migrations/$FRESH_MIGRATION")" ]]
}
minutes_since() { echo $((($(date +%s) - $1) / 60)); }

# The account and its login. wrangler.jsonc pins the account; nothing inherited may redirect it: not an account
# id, and not an API token, which would override every login.
clean_cloudflare_env() {
  local v set=""
  for v in CLOUDFLARE_ACCOUNT_ID CF_ACCOUNT_ID CLOUDFLARE_API_TOKEN CF_API_TOKEN CLOUDFLARE_API_KEY CF_API_KEY \
           CLOUDFLARE_EMAIL CF_EMAIL CLOUDFLARE_AUTH_PROFILE; do
    [[ -n "${!v:-}" ]] && set+=" $v"
    unset "$v"
  done
  [[ -z "$set" ]] || note "Ignoring these variables from your shell:$set (tonight signs in through wrangler)."
}
# login_reaches PROFILE: read only. Does that wrangler login's account list hold the shared account?
login_reaches() {
  CLOUDFLARE_AUTH_PROFILE="$1" "$WR" whoami --json 2> /dev/null | node -e '
    let s = ""; process.stdin.on("data", (d) => (s += d)).on("end", () => {
      try { process.exit(JSON.parse(s).accounts.some((a) => a.id === process.argv[1]) ? 0 : 1); } catch { process.exit(1); } })' "$ACCOUNT_ID"
}

before_you_start() {
  say "Tonight moves the live data onto the fresh schema, in place. You need:"
  step "access to the shared Cloudflare account, signed in with wrangler;"
  step "the right to squash-merge pull request #$SQUASH_PR into main;"
  step "the NFC Card and a phone, and about an hour."
  if [[ -n "$(git status --porcelain)" ]]; then
    warn "Run this from a clean checkout: git status shows changes."
    exit 1
  fi
  build_cutover || { warn "This checkout's migrations/ isn't the squash's. Check out this folder's branch, then start again."; exit 1; }
  clean_cloudflare_env
  ACCOUNT_ID=$(grep -o -E '"account_id" *: *"[0-9a-f]{32}"' "$CONFIG" | grep -o -E '[0-9a-f]{32}' | head -n 1 || true)
  [[ -n "$ACCOUNT_ID" ]] || { warn "wrangler.jsonc names no account_id."; exit 1; }
  show "wrangler whoami --json   (read only)"
  # The move's named login first (npx wrangler auth create csa-shared), then the plain `wrangler login`.
  local p
  for p in csa-shared default; do
    if login_reaches "$p"; then export CLOUDFLARE_AUTH_PROFILE="$p"; break; fi
  done
  if [[ -z "${CLOUDFLARE_AUTH_PROFILE:-}" ]]; then
    warn "No wrangler login reaches the shared account ($ACCOUNT_ID)."
    note "Sign in as a login that belongs to it: npx wrangler login, then start again."
    exit 1
  fi
  say "✓ Shared account $ACCOUNT_ID, through the wrangler login \"$CLOUDFLARE_AUTH_PROFILE\"."
  LIVE_ORIGIN=$(grep -o -E 'Live site: <https://[^>]+>' "$REPO/README.md" | head -n 1 | sed -E 's/.*<(.*)>/\1/' || true)
  [[ -n "$LIVE_ORIGIN" ]] || ask_valid LIVE_ORIGIN "The live site's address (https://...):" '^https://[^/]+$' "Like https://csa-id.example.workers.dev"
  load NFC_SLUG BOOKMARK_BEFORE_RELEASE OLD_APP_VERSION RELEASED_AT BOOKMARK_BEFORE_CUTOVER CUTOVER_AT KEPT_AT
  # Asked only before the release: after the merge, these answers no longer decide anything.
  if (($1 <= 3)) && [[ -z "$RELEASED_AT" ]]; then
    confirm "Was the move to the shared account (#95) kept, and has its cleanup run?" ||
      { warn "Wait for that first, so there's only one fallback to reason about at a time."; exit 1; }
    confirm "Is Workers Builds connected in the shared account, deploying main?" ||
      { warn "Stage 3 waits for its deploy. Connect it first (see #95)."; exit 1; }
    confirm "Were the Peer Advisers told not to edit their Profiles tonight, and is nobody in a tutoring session?" ||
      { warn "Pick another evening."; exit 1; }
  fi
}

stage_1() {
  stage "Count the live database (read only)"
  local state
  state=$(db_state live) || { warn "Couldn't read the live database. Is wrangler signed in to the shared account?"; exit 1; }
  case "$state" in
    old) ;;
    cutover) warn "The cutover already ran: resume at stage 5 (bash $0 5)."; exit 1 ;;
    clean) say "✓ The live database is already on the fresh schema, cleaned up. Nothing to do."; exit 0 ;;
    *) warn "The live database is neither at the five old migrations nor at the fresh 0000. Stop and look:"
       rows live "SELECT name FROM d1_migrations ORDER BY id" | indent; exit 1 ;;
  esac
  has_old_tables live || { warn "The live database holds tables the backup wouldn't export. Stop and look."; exit 1; }
  counts live > "$OUT/counts-before.txt" || { warn "Couldn't count the live database."; exit 1; }
  indent < "$OUT/counts-before.txt"
  say "These go in #104 with the counts after; stage 7 prints both."
  pause
}

stage_2() {
  stage "Back up: a Time Travel bookmark, an export, and tonight's cutover on a local copy"
  [[ "$(db_state live)" == old ]] || { warn "The live database isn't on the old schema any more: this stage comes before the cutover."; exit 1; }
  local bookmark version dir
  show "wrangler d1 time-travel info csa-id --json"
  bookmark=$(current_bookmark) || { warn "Couldn't read a Time Travel bookmark. Nothing changed. Re-run: bash $0 2"; exit 1; }
  write_env BOOKMARK_BEFORE_RELEASE "$bookmark"
  show "wrangler deployments list --json   (the version the site serves now, for the undo)"
  version=$(live_version) || version=""
  [[ "$version" =~ ^[0-9a-f-]{36}$ ]] || { warn "Couldn't read the live Worker's version id. Nothing changed. Re-run: bash $0 2"; exit 1; }
  write_env OLD_APP_VERSION "$version"
  say "Exporting the structure, then every table's rows, parents first (read only)."
  counts live > "$OUT/counts-export.txt" || { warn "Couldn't count the live database."; exit 1; }
  must "The export failed, and nothing changed anywhere. Re-run: bash $0 2" export_backup
  note "out/ now holds Peer Advisers' names, emails and student numbers. Stage 7 deletes them."
  say "Now tonight's cutover on a local copy of that backup. Nothing remote changes."
  dir=$(mktemp -d)
  if command -v cygpath > /dev/null 2>&1; then dir=$(cygpath -m "$dir"); fi
  if dry_run "$dir"; then
    rm -rf "$dir"
    say "✓ The backup restores into an empty database, and cutover.sql and verify.sql pass on it."
    note "The field/before/after list above is what the cutover changes. Tell those Peer Advisers afterwards."
  else
    rm -rf "$dir"
    warn "The dry run failed (above), and nothing has changed anywhere. Don't release #$SQUASH_PR tonight."
    exit 1
  fi
  pause
}

stage_3() {
  stage "Release #$SQUASH_PR: squash-merge it into main, then wait for the deploy"
  if [[ -z "$RELEASED_AT" ]]; then
    [[ "$(db_state live)" == old ]] || { warn "The live database isn't on the old schema: stop and look."; exit 1; }
    [[ -n "$OLD_APP_VERSION" ]] || { warn "Stage 2 hasn't recorded the version the undo rolls back to. Run it first: bash $0 2"; exit 1; }
    must "Couldn't fetch #$SQUASH_PR from GitHub." git fetch --quiet origin "pull/$SQUASH_PR/head"
    same_fresh_schema FETCH_HEAD ||
      { warn "#$SQUASH_PR's 0000 differs from the one cutover.sql is built from. Update this branch onto #$SQUASH_PR, then start again."; exit 1; }
    say "Merging deploys the new code. Until stage 4 finishes, about a minute later, the site runs the new code"
    say "on the old schema: Profile pages and saves fail, and no data is harmed. Go straight on afterwards."
    open_url "https://github.com/$GITHUB_REPO/pull/$SQUASH_PR"
    step "Select Ready for review. Once the checks pass, select Squash and merge, then Confirm."
    confirm "Merged?" || { warn "Stopped before the release, and nothing changed. Re-run: bash $0 3"; exit 1; }
    write_env RELEASED_AT "$(date +%s)"
    note "The 30 minutes to keep or undo run from now."
  fi
  say "Waiting for Workers Builds to deploy the merge. It usually takes a few minutes."
  show "wrangler deployments list --json   (every 15 seconds, read only)"
  local i version=""
  while true; do
    for ((i = 0; i < 60; i++)); do
      version=$(live_version 2> /dev/null) || version=""
      [[ -z "$version" || "$version" == "$OLD_APP_VERSION" ]] || break 2
      printf '.'
      sleep 15
    done
    printf '\n'
    confirm "No new deploy after 15 minutes. Keep waiting?" ||
      { warn "Look at the Workers Builds run in the dashboard, then resume: bash $0 3"; exit 1; }
  done
  printf '\n'
  say "✓ A new version serves the site: $version"
  open_url "https://dash.cloudflare.com/$ACCOUNT_ID/workers-and-pages"
  step "Select csa-id, then Deployments: the newest is the merge of #$SQUASH_PR, built by Workers Builds."
  confirm "Is it the merge of #$SQUASH_PR?" ||
    { warn "Find out what deployed before going on. To undo the release alone: bash $0 6"; exit 1; }
}

stage_4() {
  stage "The cutover: one file, all or nothing"
  local state bookmark
  state=$(db_state live) || { warn "Couldn't read the live database."; exit 1; }
  if [[ "$state" == cutover || "$state" == clean ]]; then
    note "The cutover already ran (the live database is $state)."
    pause
    return
  fi
  [[ "$state" == old ]] || { warn "The live database is in a state this wizard doesn't know. Undo in stage 6: bash $0 6"; exit 1; }
  [[ -n "$RELEASED_AT" ]] || { warn "Release #$SQUASH_PR first (stage 3): the code on main now can't read the fresh schema."; exit 1; }
  must "Couldn't fetch main from GitHub." git fetch --quiet origin main
  same_fresh_schema origin/main ||
    { warn "main's 0000 differs from the one cutover.sql is built from. Don't run it: undo the release in stage 6."; exit 1; }
  must "Couldn't build cutover.sql." build_cutover
  show "wrangler d1 time-travel info csa-id --json"
  bookmark=$(current_bookmark) || { warn "Couldn't read a Time Travel bookmark, so there'd be no undo. Nothing changed. Re-run: bash $0 4"; exit 1; }
  write_env BOOKMARK_BEFORE_CUTOVER "$bookmark"
  say "The undo point, just before the cutover: $bookmark"
  confirm "Run cutover.sql on the live database now?" ||
    { warn "Stopped. The site still runs the new code on the old schema: run this stage again, or undo in stage 6."; exit 1; }
  show "wrangler d1 execute csa-id --remote --file scripts/fresh-schema-cutover/cutover.sql -y"
  if ! run_cutover live 2>&1 | tee "$OUT/cutover.log"; then
    state=$(db_state live) || state=unreadable
    if [[ "$state" == old ]]; then
      warn "The cutover failed, and D1 rolled the whole file back: the live database is unchanged."
      note "Read the error above. Fix it and run this stage again now (bash $0 4), or undo the release (bash $0 6)."
    else
      warn "The cutover failed, and the live database is now '$state'. Undo right away: bash $0 6"
    fi
    exit 1
  fi
  [[ "$(db_state live)" == cutover ]] || { warn "cutover.sql finished, but the database doesn't look cut over. Undo: bash $0 6"; exit 1; }
  write_env CUTOVER_AT "$(date +%s)"
  say "✓ Cut over. The old rows stay in the old_* tables until stage 7."
  note "Note the rows wrangler says it wrote, above, for #104; stage 7's summary repeats them."
  pause
}

stage_5() {
  stage "Verify, then open the NFC Card's Profile"
  [[ "$(db_state live)" == cutover ]] ||
    { warn "verify.sql reads the old_* copies, which only exist between the cutover and the cleanup."; exit 1; }
  show "verify.sql on the live database (read only)"
  local rc=0
  report live "$HERE/verify.sql" || rc=$?
  case "$rc" in
    0) say "✓ verify.sql found no problem." ;;
    1) warn "verify.sql found problems: the rows marked \"problem\" above. Undo in stage 6 unless you understand each one." ;;
    *) warn "verify.sql didn't run. Re-run: bash $0 5"; exit 1 ;;
  esac
  ask_valid NFC_SLUG "The Slug on the NFC Card (like ana-reyes):" '^[a-z0-9-]{3,64}$' "Lowercase letters, digits and hyphens."
  write_env NFC_SLUG "$NFC_SLUG"
  open_url "$LIVE_ORIGIN/id/$NFC_SLUG"
  step "The Profile shows, with its photo and Social Links. Tap the NFC Card with a phone too."
  open_url "$LIVE_ORIGIN/login"
  step "Sign in with Google. Everyone signs in again tonight: Sessions weren't carried."
  step "You land on your own dashboard. Save your Profile once, unchanged, to see that saving works."
  if confirm "Does everything look right?"; then say "✓ Then keep it, in the next stage."
  else warn "Then undo it, in the next stage."; fi
  pause
}

stage_6() {
  stage "Keep or undo, within 30 minutes of the release"
  if [[ -n "$KEPT_AT" ]]; then
    note "Kept at $(when "$KEPT_AT")."
    pause
    return
  fi
  if [[ -n "$RELEASED_AT" ]]; then
    say "#$SQUASH_PR was released $(minutes_since "$RELEASED_AT") minute(s) ago, at $(when "$RELEASED_AT")."
    (($(minutes_since "$RELEASED_AT") < 30)) ||
      warn "After 30 minutes, an undo throws away edits made since the cutover. Prefer fixing forward."
  fi
  if confirm "Keep the fresh schema?"; then
    write_env KEPT_AT "$(date +%s)"
    say "✓ Kept. Last, drop the old copies."
    pause
    return
  fi
  undo
}

# undo: the database back to the bookmark taken just before the cutover, then the Worker back to the version
# from before the release. Database first: until the rollback, the new code meets the old schema, the same
# brief state as between the release and the cutover.
undo() {
  local state result previous
  say "The undo puts the database back as it was just before the cutover, then rolls the Worker back to the"
  say "version that served the site before the release. Edits made since the cutover are lost."
  state=$(db_state live) || state=unreadable
  if [[ "$state" != old ]]; then
    [[ -n "$BOOKMARK_BEFORE_CUTOVER" ]] || {
      warn "Stage 4 recorded no bookmark. Find the one for just before the cutover:"
      note "npx wrangler d1 time-travel info csa-id --timestamp <RFC 3339 time just before it>"
      exit 1
    }
    confirm "Restore the live database to $BOOKMARK_BEFORE_CUTOVER?" || exit 1
    show "wrangler d1 time-travel restore csa-id --bookmark $BOOKMARK_BEFORE_CUTOVER --json"
    result=$("$WR" d1 time-travel restore "$DB_NAME" --bookmark "$BOOKMARK_BEFORE_CUTOVER" --json --config "$CONFIG") ||
      { warn "The restore failed. Try it by hand: npx wrangler d1 time-travel restore csa-id --bookmark=$BOOKMARK_BEFORE_CUTOVER"; exit 1; }
    previous=$(json_field previous_bookmark <<< "$result" || true)
    [[ -z "$previous" ]] || note "To undo the restore itself: npx wrangler d1 time-travel restore csa-id --bookmark=$previous"
    state=$(db_state live) || state=unreadable
    [[ "$state" == old ]] || { warn "After the restore the live database is '$state', not the old schema. Stop and look."; exit 1; }
    say "✓ The database is back on the old schema."
  fi
  [[ -n "$OLD_APP_VERSION" ]] || { warn "No version from before the release is recorded. Find it: npx wrangler deployments list"; exit 1; }
  confirm "Roll the Worker back to $OLD_APP_VERSION, the version from before the release?" || exit 1
  must "The rollback failed. Try: npx wrangler rollback $OLD_APP_VERSION" \
    "$WR" rollback "$OLD_APP_VERSION" -m "Undo the fresh-schema cutover (#104)" -y --config "$CONFIG"
  counts live > "$OUT/counts-undone.txt" || true
  if [[ -s "$OUT/counts-before.txt" ]] && cmp -s "$OUT/counts-before.txt" "$OUT/counts-undone.txt"; then
    say "✓ The live database holds what it held at stage 1."
    rm -f "$OUT/before-schema.sql" "$OUT/before-data.sql"
    note "Deleted the backup from out/: it holds personal data, and the live database is whole again."
  else
    warn "The counts differ from stage 1's (out/counts-before.txt, out/counts-undone.txt). The backup stays in out/."
  fi
  write_env UNDONE_AT "$(date +%s)"
  warn "main still holds #$SQUASH_PR, and every merge into main deploys. Revert it before anything else merges."
  open_url "https://github.com/$GITHUB_REPO/pull/$SQUASH_PR"
  step "Select Revert, then merge the pull request GitHub opens."
  note "To try again another evening: re-apply #$SQUASH_PR and run this wizard from stage 1."
  finish
  exit 0
}

stage_7() {
  stage "Clean up: drop the old copies and the backup"
  [[ -n "$KEPT_AT" ]] || { warn "Drop the copies only after keeping the cutover: bash $0 6"; exit 1; }
  local state written
  state=$(db_state live) || { warn "Couldn't read the live database."; exit 1; }
  if [[ "$state" == cutover ]]; then
    say "Drops the old_* tables holding tonight's copies of the old rows. Time Travel can still go back to the"
    say "bookmark from stage 4 for as long as D1 keeps it (7 days on the Free plan), losing every edit since."
    confirm "Drop the old copies now?" || exit 1
    must "cleanup.sql failed. Re-run: bash $0 7" run_cleanup live
  fi
  [[ "$(db_state live)" == clean ]] || { warn "The live database doesn't look cleaned up. Stop and look."; exit 1; }
  counts live > "$OUT/counts-after.txt" || { warn "Couldn't count the live database. Re-run: bash $0 7"; exit 1; }
  rm -f "$OUT/before-schema.sql" "$OUT/before-data.sql" "$OUT/counts-export.txt" "$OUT/counts-restored.txt"
  say "✓ Dropped the copies, and deleted the backup from out/ (it held personal data)."
  written=$(grep -o -E '[0-9]+ rows written' "$OUT/cutover.log" 2> /dev/null | tail -n 1 || true)
  touch "$OUT/counts-before.txt" # stage 1 ran on another machine: the summary's "before" column stays empty
  {
    printf '## Fresh-schema cutover, %s\n\n' "$(when "${CUTOVER_AT:-$KEPT_AT}")"
    printf '| | before | after |\n| --- | ---: | ---: |\n'
    awk -F '\t' 'NR == FNR { before[$1] = $2; next } { printf "| %s | %s | %s |\n", $1, before[$1], $2 }' \
      "$OUT/counts-before.txt" "$OUT/counts-after.txt"
    printf '\n- Released #%s: %s\n' "$SQUASH_PR" "$( [[ -n "$RELEASED_AT" ]] && when "$RELEASED_AT")"
    printf -- '- Cut over: %s (%s)\n' "$( [[ -n "$CUTOVER_AT" ]] && when "$CUTOVER_AT")" "${written:-rows written: see out/cutover.log}"
    printf -- '- Kept: %s, %s minutes after the release\n' "$(when "$KEPT_AT")" "$(( (KEPT_AT - ${RELEASED_AT:-$KEPT_AT}) / 60 ))"
  } > "$OUT/summary.md"
  printf '\n'
  indent < "$OUT/summary.md"
  printf '\n'
  say "Paste this into #104 (it's in out/summary.md), then delete scripts/fresh-schema-cutover/ in a pull request."
  finish
}

run_wizard() {
  ENV_FILE="$HERE/.cutover.env"
  cd "$REPO"
  mkdir -p "$OUT"
  local from="${1:-1}" i
  [[ "$from" =~ ^[1-7]$ ]] || { printf 'Usage: bash %s [stage to resume from, 1 to 7]\n' "$0"; exit 2; }
  TOTAL_STAGES=7
  banner "CSA-ID · the fresh-schema cutover (#104)"
  before_you_start "$from"
  for ((i = from; i <= 7; i++)); do
    _STAGE_INDEX=$((i - 1))
    "stage_$i"
  done
}

run_wizard "$@"; exit
